const express = require('express');
const Pool = require('pg-pool');

const app = express();

const companyPools = new Map();

function getCompanyPool(companyId) {
  if (!companyPools.has(companyId)) {
    companyPools.set(
      companyId,
      new Pool({
        database: `company_${companyId}`,
        host: 'pg-hr-cluster.internal',
        user: 'hr_reader',
        password: process.env.HR_DB_PASSWORD
      })
    );
  }
  return companyPools.get(companyId);
}

app.get('/api/payroll/employees/search/:companyId', async (req, res) => {
  if (!req.user || !req.user.companyId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { companyId } = req.params;
  const { query } = req.query;

  // Confirm caller belongs to the requested company and has HR role
  if (req.user.companyId !== companyId) {
    return res.status(403).json({ error: 'Access denied: cannot query payroll database of another company' });
  }

  if (!req.user.roles || !req.user.roles.includes('HR_OFFICER')) {
    return res.status(403).json({ error: 'Access denied: HR officer privileges required' });
  }

  const pool = getCompanyPool(companyId);

  try {
    const { rows } = await pool.query(
      'SELECT id, full_name, salary, bank_account FROM payroll_records WHERE full_name ILIKE $1',
      [`%${query || ''}%`]
    );
    res.json({ companyId, employees: rows });
  } catch (err) {
    res.status(500).json({ error: 'Payroll search failed' });
  }
});

app.listen(9105);
